#include <iostream>
#include <vector>
using namespace std;

class Section {
private:
    int _begin, _end;
public:
    Section(int b, int e) : _begin(b), _end(e) {}
    int begin() const { return _begin; }
    int end() const { return _end; }
    int length() const { return end() - begin(); }
};

vector<Section> sections;
bool card[100002];
int K, N;

int main() {
    while (true) {
        fill(card, card + 100002, false);
        sections.clear();
        cin >> N >> K;
        if (N == 0) break;
        for (int i = 0; i < K; i++) {
            int a;
            cin >> a;
            card[a] = true;
        }
        int st = -1, ans = 0;
        for (int i = 1; i <= N + 1; i++) {
            if (card[i]) {
                if (st == -1) {
                    st = i;  // mark the start of a new section
                }
            } else {
                if (st != -1) {
                    sections.emplace_back(st, i);  // create a new section
                    st = -1;  // reset start
                }
            }
        }
        for (const Section& sec : sections) {
            if (card[0]) {
                ans = max(ans, sec.length() + 1);  // account for the zero card
            }
            ans = max(ans, sec.length());
        }
        if (card[0]) {
            for (size_t i = 0; i < sections.size() - 1; ++i) {
                if (sections[i].end() + 1 == sections[i + 1].begin()) {
                    ans = max(ans, sections[i].length() + sections[i + 1].length() + 1);
                }
            }
        }
        cout << ans << endl;
    }
}

